1	package zkcircuit
2	
3	import (
4		"bytes"
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"errors"
9		"fmt"
10		"hash"
11		"io"
12		"math/big"
13		"sort"
14	)
15	
16	// This file implements R1CS-style constraint definitions: their strict JSON
17	// form, validation against the declared wire layout of a circuit version, a
18	// canonical form used both for persistence and for artifact hashing, and the
19	// modular a·b = c evaluation used by input checking.
20	
21	// maxModulus bounds accepted moduli. The bound keeps every reduced field
22	// element and coefficient inside int32, which makes all constraint
23	// arithmetic exact in int64 (a product of two residues is at most
24	// (p-1)^2 < 2^62).
25	const maxModulus = 2147483647
26	
27	// Term is one wire reference with its coefficient: coeff * value(wire).
28	type Term struct {
29		Wire  int    `json:"wire"`
30		Coeff string `json:"coeff"`
31	}
32	
33	// Constraint is one a·b = c equation modulo the definition's field. Each
34	// slice is a sum of terms; an empty slice is the zero linear combination.
35	type Constraint struct {
36		A []Term `json:"a"`
37		B []Term `json:"b"`
38		C []Term `json:"c"`
39	}
40	
41	// Definition is an importable constraint set. The JSON file carries modulus
42	// as a decimal string and an ordered constraints array.
43	type Definition struct {
44		Modulus     string       `json:"modulus"`
45		Constraints []Constraint `json:"constraints"`
46	}
47	
48	// Artifact is the result of compiling one frozen circuit version. It binds
49	// the version's name, version number, modulus and constraint count to a
50	// stable SHA-256 hash; the same logical circuit always compiles to the same
51	// artifact.
52	type Artifact struct {
53		Name        string
54		Version     int
55		Modulus     int
56		Constraints int
57		Hash        string
58	}
59	
60	// CheckResult is the verdict of testing one input assignment against a
61	// compiled artifact. Satisfied reports whether every constraint holds;
62	// FirstFailure is the 1-based index of the first failing constraint, zero
63	// when the assignment satisfies the circuit.
64	type CheckResult struct {
65		Satisfied    bool
66		Hash         string
67		FirstFailure int
68	}
69	
70	// Witness is one input assignment: values for the declared public and
71	// private wires, in declaration order. Values are arbitrary-length signed
72	// decimal strings interpreted modulo the circuit's field.
73	type Witness struct {
74		Public  []string
75		Private []string
76	}
77	
78	// ---- parsed / canonical in-memory representation -------------------------
79	
80	// parsedTerm is a validated term whose coefficient has been reduced into
81	// [0, modulus).
82	type parsedTerm struct {
83		wire  int
84		value int64 // coefficient mod modulus
85	}
86	
87	// canonicalConstraint groups merged terms by wire.
88	type canonicalConstraint struct {
89		a, b, c []parsedTerm
90	}
91	
92	// canonicalDefinition is a fully validated constraint set in its canonical
93	// form: terms merged per wire, reduced modulo p, zeros removed, wires sorted
94	// ascending within each linear combination.
95	type canonicalDefinition struct {
96		modulus     int64
97		public      int
98		private     int
99		constraints []canonicalConstraint
100	}
101	
102	// maxWire returns the largest wire index referenced anywhere.
103	func (d *canonicalDefinition) maxWire() int {
104		max := 0
105		for _, con := range d.constraints {
106			for _, group := range [][]parsedTerm{con.a, con.b, con.c} {
107				for _, t := range group {
108					if t.wire > max {
109						max = t.wire
110					}
111				}
112			}
113		}
114		return max
115	}
116	
117	// compatibleWith reports whether the definition stays legal when its
118	// version declares the given counts: the constraint count must match and
119	// every referenced wire must still lie inside the declared layout.
120	func (d *canonicalDefinition) compatibleWith(constraints, public, private int) bool {
121		if len(d.constraints) != constraints {
122			return false
123		}
124		return d.maxWire() <= public+private
125	}
126	
127	// toExport renders the canonical form as the public Definition type, with
128	// coefficients reduced to decimal strings in [0, modulus).
129	func (d *canonicalDefinition) toExport() Definition {
130		combo := func(terms []parsedTerm) []Term {
131			r := make([]Term, 0, len(terms))
132			for _, t := range terms {
133				r = append(r, Term{Wire: t.wire, Coeff: fmt.Sprintf("%d", t.value)})
134			}
135			return r
136		}
137		cons := make([]Constraint, 0, len(d.constraints))
138		for _, con := range d.constraints {
139			cons = append(cons, Constraint{A: combo(con.a), B: combo(con.b), C: combo(con.c)})
140		}
141		return Definition{Modulus: fmt.Sprintf("%d", d.modulus), Constraints: cons}
142	}
143	
144	// ---- strict JSON helpers --------------------------------------------------
145	
146	// strictObject decodes raw as a JSON object whose keys must all be allowed,
147	// rejecting syntax errors, trailing data, duplicates, non-objects and
148	// unknown keys. It returns the raw members for typed decoding.
149	func strictObject(raw []byte, allowed []string, what string) (map[string]json.RawMessage, error) {
150		trimmed := bytes.TrimSpace(raw)
151		if len(trimmed) == 0 || trimmed[0] != '{' {
152			return nil, invalidf("%s must be a JSON object", what)
153		}
154		var members map[string]json.RawMessage
155		if err := json.Unmarshal(trimmed, &members); err != nil {
156			// Unmarshal also rejects trailing data after the top-level value.
157			return nil, invalidf("%s is not valid JSON: %v", what, err)
158		}
159		allowedSet := make(map[string]bool, len(allowed))
160		for _, k := range allowed {
161			allowedSet[k] = true
162		}
163		for key := range members {
164			if !allowedSet[key] {
165				return nil, invalidf("%s has unknown field %q", what, key)
166			}
167		}
168		if err := rejectDuplicateKeys(trimmed, what); err != nil {
169			return nil, err
170		}
171		return members, nil
172	}
173	
174	// rejectDuplicateKeys walks the JSON token stream rejecting any object that
175	// names the same key twice; encoding/json silently keeps the last value.
176	func rejectDuplicateKeys(raw []byte, what string) error {
177		dec := json.NewDecoder(bytes.NewReader(raw))
178		dec.UseNumber()
179		var walk func() error
180		walk = func() error {
181			tok, err := dec.Token()
182			if err != nil {
183				return invalidf("%s is not valid JSON: %v", what, err)
184			}
185			delim, ok := tok.(json.Delim)
186			if !ok {
187				return nil // scalar
188			}
189			switch delim {
190			case '{':
191				seen := make(map[string]bool)
192				for dec.More() {
193					keyTok, err := dec.Token()
194					if err != nil {
195						return invalidf("%s is not valid JSON: %v", what, err)
196					}
197					key := keyTok.(string)
198					if seen[key] {
199						return invalidf("%s contains duplicate field %q", what, key)
200					}
201					seen[key] = true
202					if err := walk(); err != nil {
203						return err
204					}
205				}
206				if _, err := dec.Token(); err != nil { // closing brace
207					return invalidf("%s is not valid JSON: %v", what, err)
208				}
209			case '[':
210				for dec.More() {
211					if err := walk(); err != nil {
212						return err
213					}
214				}
215				if _, err := dec.Token(); err != nil { // closing bracket
216					return invalidf("%s is not valid JSON: %v", what, err)
217				}
218			}
219			return nil
220		}
221		return walk()
222	}
223	
224	func requireMember(members map[string]json.RawMessage, key, what string) (json.RawMessage, error) {
225		raw, ok := members[key]
226		if !ok {
227			return nil, invalidf("%s is missing required field %q", what, key)
228		}
229		return raw, nil
230	}
231	
232	// decodeJSONString requires raw to be a JSON string and returns it.
233	func decodeJSONString(raw json.RawMessage, what string) (string, error) {
234		if string(bytes.TrimSpace(raw)) == "null" {
235			return "", invalidf("%s must be a JSON string, not null", what)
236		}
237		var s string
238		if err := json.Unmarshal(raw, &s); err != nil {
239			return "", invalidf("%s must be a JSON string: %v", what, err)
240		}
241		return s, nil
242	}
243	
244	// decodeJSONInt requires raw to be a JSON integer (no floats, strings,
245	// null).
246	func decodeJSONInt(raw json.RawMessage, what string) (int, error) {
247		trimmed := bytes.TrimSpace(raw)
248		if string(trimmed) == "null" || len(trimmed) == 0 {
249			return 0, invalidf("%s must be a JSON integer, not null", what)
250		}
251		if trimmed[0] != '-' && (trimmed[0] < '0' || trimmed[0] > '9') {
252			return 0, invalidf("%s must be a JSON integer", what)
253		}
254		var n int
255		if err := json.Unmarshal(raw, &n); err != nil {
256			return 0, invalidf("%s must be a JSON integer: %v", what, err)
257		}
258		return n, nil
259	}
260	
261	// ---- definition parsing ---------------------------------------------------
262	
263	// parseDefinitionJSON parses and fully validates a definition document
264	// against the version's declared counts.
265	//
266	// Rejected inputs include malformed JSON, trailing data, duplicate/unknown
267	// or missing fields (top level, per constraint and per term), a non-prime or
268	// out-of-range modulus, malformed coefficients, wire indexes outside
269	// [0, 1+public+private) and a constraint count that does not equal the
270	// circuit version's declared count. The wire layout is wire 0 = constant 1,
271	// followed by the declared public inputs and then the private inputs.
272	func parseDefinitionJSON(raw []byte, public, private, wantCount int) (*canonicalDefinition, error) {
273		members, err := strictObject(raw, []string{"modulus", "constraints"}, "constraint definition")
274		if err != nil {
275			return nil, err
276		}
277		modulusRaw, err := requireMember(members, "modulus", "constraint definition")
278		if err != nil {
279			return nil, err
280		}
281		constraintsRaw, err := requireMember(members, "constraints", "constraint definition")
282		if err != nil {
283			return nil, err
284		}
285		modulusText, err := decodeJSONString(modulusRaw, "modulus")
286		if err != nil {
287			return nil, err
288		}
289		p, err := parseModulus(modulusText)
290		if err != nil {
291			return nil, err
292		}
293		if string(bytes.TrimSpace(constraintsRaw)) == "null" {
294			return nil, invalidf("constraint definition field \"constraints\" must be an array")
295		}
296		var constraintRaws []json.RawMessage
297		if err := json.Unmarshal(constraintsRaw, &constraintRaws); err != nil {
298			return nil, invalidf("constraint definition field \"constraints\" must be an array: %v", err)
299		}
300		if len(constraintRaws) != wantCount {
301			return nil, invalidf("constraint count mismatch: definition has %d constraints, version declares %d",
302				len(constraintRaws), wantCount)
303		}
304	
305		parsed := &canonicalDefinition{
306			modulus:     p,
307			public:      public,
308			private:     private,
309			constraints: make([]canonicalConstraint, 0, len(constraintRaws)),
310		}
311		maxIndex := public + private
312		for i, craw := range constraintRaws {
313			con, err := parseConstraint(craw, p, maxIndex)
314			if err != nil {
315				return nil, fmt.Errorf("constraint #%d: %w", i+1, err)
316			}
317			parsed.constraints = append(parsed.constraints, con)
318		}
319		return parsed, nil
320	}
321	
322	// parseConstraint parses one {"a":[…],"b":[…],"c":[…]} object.
323	func parseConstraint(raw json.RawMessage, p int64, maxIndex int) (canonicalConstraint, error) {
324		members, err := strictObject(raw, []string{"a", "b", "c"}, "constraint")
325		if err != nil {
326			return canonicalConstraint{}, err
327		}
328		var out canonicalConstraint
329		for _, side := range []struct {
330			key string
331			dst *[]parsedTerm
332		}{
333			{"a", &out.a}, {"b", &out.b}, {"c", &out.c},
334		} {
335			sideRaw, err := requireMember(members, side.key, "constraint")
336			if err != nil {
337				return canonicalConstraint{}, err
338			}
339			terms, err := parseLinearCombo(sideRaw, p, maxIndex, side.key)
340			if err != nil {
341				return canonicalConstraint{}, err
342			}
343			*side.dst = terms
344		}
345		return out, nil
346	}
347	
348	// parseLinearCombo parses an array of {"wire":int,"coeff":string} terms and
349	// returns the canonical combination: duplicate wires merged, coefficients
350	// reduced modulo p, zeros dropped, wires sorted ascending.
351	func parseLinearCombo(raw json.RawMessage, p int64, maxIndex int, side string) ([]parsedTerm, error) {
352		if string(bytes.TrimSpace(raw)) == "null" {
353			return nil, invalidf("constraint side %q must be an array", side)
354		}
355		var termRaws []json.RawMessage
356		if err := json.Unmarshal(raw, &termRaws); err != nil {
357			return nil, invalidf("constraint side %q must be an array: %v", side, err)
358		}
359		bigP := big.NewInt(p)
360		merged := make(map[int]*big.Int)
361		for j, traw := range termRaws {
362			members, err := strictObject(traw, []string{"wire", "coeff"}, fmt.Sprintf("term %s[%d]", side, j))
363			if err != nil {
364				return nil, err
365			}
366			wireRaw, err := requireMember(members, "wire", fmt.Sprintf("term %s[%d]", side, j))
367			if err != nil {
368				return nil, err
369			}
370			coeffRaw, err := requireMember(members, "coeff", fmt.Sprintf("term %s[%d]", side, j))
371			if err != nil {
372				return nil, err
373			}
374			wire, err := decodeJSONInt(wireRaw, fmt.Sprintf("term %s[%d] wire", side, j))
375			if err != nil {
376				return nil, err
377			}
378			if wire < 0 || wire > maxIndex {
379				return nil, invalidf("term %s[%d] references wire %d outside [0,%d]", side, j, wire, maxIndex)
380			}
381			coeffText, err := decodeJSONString(coeffRaw, fmt.Sprintf("term %s[%d] coefficient", side, j))
382			if err != nil {
383				return nil, err
384			}
385			coeff, err := parseBigSignedDecimal(coeffText)
386			if err != nil {
387				return nil, invalidf("term %s[%d] coefficient %q is not a decimal integer: %v", side, j, coeffText, err)
388			}
389			coeff.Mod(coeff, bigP) // into [0,p); Go's Mod keeps the sign of p
390			if existing, ok := merged[wire]; ok {
391				existing.Add(existing, coeff)
392				existing.Mod(existing, bigP)
393			} else {
394				merged[wire] = new(big.Int).Set(coeff)
395			}
396		}
397		out := make([]parsedTerm, 0, len(merged))
398		for wire, value := range merged {
399			v := value.Int64()
400			if v == 0 {
401				continue // canonical form drops zero terms
402			}
403			out = append(out, parsedTerm{wire: wire, value: v})
404		}
405		sort.Slice(out, func(i, j int) bool { return out[i].wire < out[j].wire })
406		return out, nil
407	}
