520	// ---- artifact hashing -----------------------------------------------------
521	
522	// artifactHash computes the stable SHA-256 of a compiled version. It folds
523	// in everything the version's correctness depends on: name, version,
524	// modulus, the public/private split and the ordered, canonical constraints.
525	//
526	// Consequently only semantically equivalent rewrites hash alike: JSON
527	// whitespace, term order, duplicate terms that merge, added/removed zero
528	// terms, and coefficients differing by a multiple of the modulus. Constraint
529	// order, modulus, name, version and the input partition change the hash.
530	func artifactHash(name string, version int, d *canonicalDefinition) string {
531		h := sha256.New()
532		writeLine := func(prefix, value string) {
533			io.WriteString(h, prefix+"="+value+"\n")
534		}
535		writeLine("name", name)
536		writeLine("version", fmt.Sprintf("%d", version))
537		writeLine("modulus", fmt.Sprintf("%d", d.modulus))
538		writeLine("public_inputs", fmt.Sprintf("%d", d.public))
539		writeLine("private_inputs", fmt.Sprintf("%d", d.private))
540		writeLine("constraint_count", fmt.Sprintf("%d", len(d.constraints)))
541		for i, con := range d.constraints {
542			fmt.Fprintf(h, "constraint=%d\n", i)
543			writeCombo(h, "a", con.a)
544			writeCombo(h, "b", con.b)
545			writeCombo(h, "c", con.c)
546		}
547		return hex.EncodeToString(h.Sum(nil))
548	}
549	
550	func writeCombo(h hash.Hash, side string, terms []parsedTerm) {
551		fmt.Fprintf(h, "%s=%d", side, len(terms))
552		for _, t := range terms {
553			fmt.Fprintf(h, " %d:%d", t.wire, t.value)
554		}
555		io.WriteString(h, "\n")
556	}
557	
558	// ---- canonical JSON for persistence --------------------------------------
559	
560	func (d *canonicalDefinition) toPersist() persistDefinition {
561		out := persistDefinition{
562			Modulus:     fmt.Sprintf("%d", d.modulus),
563			Constraints: make([]persistConstraint, 0, len(d.constraints)),
564		}
565		combo := func(terms []parsedTerm) []persistTerm {
566			tt := make([]persistTerm, 0, len(terms))
567			for _, t := range terms {
568				tt = append(tt, persistTerm{Wire: t.wire, Coeff: fmt.Sprintf("%d", t.value)})
569			}
570			return tt
571		}
572		for _, con := range d.constraints {
573			out.Constraints = append(out.Constraints, persistConstraint{
574				A: combo(con.a), B: combo(con.b), C: combo(con.c),
575			})
576		}
577		return out
578	}
579	
580	// definitionFromPersist re-validates a stored definition against its
581	// version's declared input counts and rebuilds its canonical form. It is
582	// used both at load time (integrity check) and before compile/check.
583	func definitionFromPersist(p persistDefinition, public, private int) (*canonicalDefinition, error) {
584		combo := func(tt []persistTerm) []Term {
585			r := make([]Term, 0, len(tt))
586			for _, t := range tt {
587				r = append(r, Term{Wire: t.Wire, Coeff: t.Coeff})
588			}
589			return r
590		}
591		cons := make([]Constraint, 0, len(p.Constraints))
592		for _, c := range p.Constraints {
593			cons = append(cons, Constraint{A: combo(c.A), B: combo(c.B), C: combo(c.C)})
594		}
595		raw, err := json.Marshal(Definition{Modulus: p.Modulus, Constraints: cons})
596		if err != nil {
597			return nil, err
598		}
599		return parseDefinitionJSON(raw, public, private, len(cons))
600	}
601	
602	// ---- input checking -------------------------------------------------------
603	
604	// parseWitness validates the check input JSON. Both arrays must be present
605	// and arrays, their lengths must match the declaration, and every value must
606	// be an arbitrarily long signed decimal string. Every rejection is reported
607	// as an input format error, distinct from domain rule failures.
608	func parseWitness(raw []byte, public, private int) (Witness, error) {
609		w, err := parseWitnessInner(raw, public, private)
610		if err != nil {
611			var se StoreError
612			if errors.As(err, &se) {
613				return Witness{}, StoreError{Kind: ErrInvalidInput.Kind, Detail: se.Detail}
614			}
615			return Witness{}, inputFormatf("%v", err)
616		}
617		return w, nil
618	}
619	
620	func parseWitnessInner(raw []byte, public, private int) (Witness, error) {
621		members, err := strictObject(raw, []string{"public", "private"}, "input")
622		if err != nil {
623			return Witness{}, err
624		}
625		publicRaw, err := requireMember(members, "public", "input")
626		if err != nil {
627			return Witness{}, err
628		}
629		privateRaw, err := requireMember(members, "private", "input")
630		if err != nil {
631			return Witness{}, err
632		}
633		parseArray := func(raw json.RawMessage, which string) ([]string, error) {
634			if string(bytes.TrimSpace(raw)) == "null" {
635				return nil, invalidf("input field %q must be an array", which)
636			}
637			var values []string
638			if err := json.Unmarshal(raw, &values); err != nil {
639				return nil, invalidf("input field %q must be an array of decimal strings: %v", which, err)
640			}
641			return values, nil
642		}
643		pubValues, err := parseArray(publicRaw, "public")
644		if err != nil {
645			return Witness{}, err
646		}
647		privValues, err := parseArray(privateRaw, "private")
648		if err != nil {
649			return Witness{}, err
650		}
651		if len(pubValues) != public {
652			return Witness{}, invalidf("public input length mismatch: got %d values, version declares %d", len(pubValues), public)
653		}
654		if len(privValues) != private {
655			return Witness{}, invalidf("private input length mismatch: got %d values, version declares %d", len(privValues), private)
656		}
657		for i, v := range pubValues {
658			if _, err := parseBigSignedDecimal(v); err != nil {
659				return Witness{}, invalidf("public input #%d value %q is not a decimal integer: %v", i+1, v, err)
660			}
661		}
662		for i, v := range privValues {
663			// The value itself is deliberately not echoed back.
664			if _, err := parseBigSignedDecimal(v); err != nil {
665				return Witness{}, invalidf("private input #%d value is not a decimal integer: %v", i+1, err)
666			}
667		}
668		return Witness{Public: pubValues, Private: privValues}, nil
669	}
670	
671	// evaluate checks every constraint against the witness and returns the
672	// 1-based index of the first failure, or 0 when all hold.
673	func (d *canonicalDefinition) evaluate(w Witness) int {
674		p := d.modulus
675		// Wire layout: 0 = 1, then public inputs, then private inputs.
676		values := make([]int64, 1+d.public+d.private)
677		values[0] = 1
678		bigP := big.NewInt(p)
679		for i, s := range w.Public {
680			n, _ := parseBigSignedDecimal(s)
681			n.Mod(n, bigP)
682			values[1+i] = n.Int64()
683		}
684		for i, s := range w.Private {
685			n, _ := parseBigSignedDecimal(s)
686			n.Mod(n, bigP)
687			values[1+d.public+i] = n.Int64()
688		}
689		combo := func(terms []parsedTerm) int64 {
690			var sum int64
691			for _, t := range terms {
692				// sum < p and the product < (p-1)^2 < 2^62, so this add never
693				// overflows int64.
694				sum = modInt64(sum+t.value*values[t.wire], p)
695			}
696			return sum
697		}
698		for i, con := range d.constraints {
699			av := combo(con.a)
700			bv := combo(con.b)
701			cv := combo(con.c)
702			if modInt64(av*bv, p) != cv {
703				return i + 1
704			}
705		}
706		return 0
707	}
708

