50	// UpdateCircuit modifies a draft circuit version. It must target an existing,
51	// unfrozen version explicitly: unknown versions yield ErrNotFound and frozen
52	// versions yield ErrFrozen. On success the counts and description are
53	// replaced as one atomic change; partial updates can never be observed.
54	func (s *Store) UpdateCircuit(c Circuit) (Circuit, error) {
55		if err := validateCircuitKey(c.Name, c.Version); err != nil {
56			return Circuit{}, err
57		}
58		if err := validateCounts(c.Constraints, c.PublicInputs, c.PrivateInputs); err != nil {
59			return Circuit{}, err
60		}
61	
62		var result Circuit
63		err := s.withLock(func() (bool, error) {
64			existing := findCircuit(s.data.Circuits, c.Name, c.Version)
65			if existing == nil {
66				return false, notFoundf("circuit %q version %d does not exist", c.Name, c.Version)
67			}
68			if existing.Frozen {
69				return false, frozenf("circuit %q version %d is frozen and its description cannot be modified", c.Name, c.Version)
70			}
71			// When a definition is already imported, changing the three counts is
72			// only accepted as a whole if the definition stays legal under them
73			// (exact constraint count, all wires inside the new input layout).
74			if existing.Definition != nil {
75				parsed, perr := definitionFromPersist(*existing.Definition, existing.PublicInputs, existing.PrivateInputs)
76				if perr != nil {
77					return false, corruptf("stored definition for %q v%d is unreadable: %v", c.Name, c.Version, perr)
78				}
79				if !parsed.compatibleWith(c.Constraints, c.PublicInputs, c.PrivateInputs) {
80					return false, invalidf("update rejected: it would make the imported constraint definition illegal (constraint count or wire layout mismatch); the whole change is refused")
81				}
82			}
83			existing.Constraints = c.Constraints
84			existing.PublicInputs = c.PublicInputs
85			existing.PrivateInputs = c.PrivateInputs
86			existing.Description = c.Description
87			result = circuitFromPersist(*existing)
88			return true, nil
89		})
90		return result, err
91	}
