func cmdCircuitList(f *cliFlags) int {
	store, code := openStore(f)
	if store == nil {
		return code
	}
	defer store.Close()

	circuits, err := store.ListCircuits()
	if err != nil {
		return reportStoreError(err)
	}
	for _, c := range circuits {
		fmt.Println("circuit:", formatCircuit(c))
	}
	return exitOK
