481	// definition is refused on open like any other read failure.
482	func TestTamperedDefinitionAndArtifactRefused(t *testing.T) {
483		dir := filepath.Join(t.TempDir(), "bench")
484		s, _ := Open(dir)
485		seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
486		s.FreezeCircuit("c", 1)
