491		dataFile := filepath.Join(dir, dirDataFile)
492	
493		tamper := func(t *testing.T, mutate func([]byte) []byte) {
494			t.Helper()
495			original, err := os.ReadFile(dataFile)
496			if err != nil {
497				t.Fatal(err)
498			}
499			bad := mutate(append([]byte(nil), original...))
500			if err := os.WriteFile(dataFile, bad, 0o644); err != nil {
501				t.Fatal(err)
502			}
503			if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
504				t.Fatalf("want data corrupt, got %v", err)
505			}
506			// File must be left untouched on refusal.
507			left, _ := os.ReadFile(dataFile)
508			if string(left) != string(bad) {
509				t.Fatal("damaged file was overwritten on refusal")
510			}
511			if err := os.WriteFile(dataFile, original, 0o644); err != nil {
512				t.Fatal(err)
513			}
514		}
515	
516		t.Run("artifact hash", func(t *testing.T) {
517			tamper(t, func(b []byte) []byte {
518				return replaceFirst(b, []byte(`"hash": "`), []byte(`"hash": "deadbeef`))
519			})
520		})
521		t.Run("definition modulus", func(t *testing.T) {
522			tamper(t, func(b []byte) []byte {
523				return replaceFirst(b, []byte(`"modulus": "7"`), []byte(`"modulus": "11"`))
524			})
525		})
526		t.Run("definition coeff", func(t *testing.T) {
527			tamper(t, func(b []byte) []byte {
528				return replaceFirst(b, []byte(`"coeff": "6"`), []byte(`"coeff": "5"`))
529			})
530		})
531		t.Run("artifact count", func(t *testing.T) {
532			tamper(t, func(b []byte) []byte {
533				return replaceFirst(b, []byte(`"constraints": 1,`), []byte(`"constraints": 2,`))
534			})
535		})
536	
537		// After restoring, the directory reads cleanly.
538		if _, err := Open(dir); err != nil {
539			t.Fatalf("restored dir should open: %v", err)
540		}
541	}
