543	func replaceFirst(haystack, marker, replacement []byte) []byte {
544		i := indexBytes(haystack, marker)
545		if i < 0 {
546			return haystack
547		}
548		out := append([]byte(nil), haystack[:i]...)
549		out = append(out, replacement...)
550		out = append(out, haystack[i+len(marker):]...)
551		return out
552	}
553	
554	func indexBytes(haystack, needle []byte) int {
555		for i := 0; i+len(needle) <= len(haystack); i++ {
556			if string(haystack[i:i+len(needle)]) == string(needle) {
557				return i
558			}
559		}
560		return -1
561	}
