563	// Concurrent import vs freeze must leave only a complete definition (old or
564	// new), never a frozen version with a half-applied or missing definition,
565	// and the on-disk state must reopen consistently.
566	func TestImportFreezeRaceCompleteness(t *testing.T) {
567		for iter := 0; iter < 20; iter++ {
568			dir := t.TempDir()
569			s, _ := Open(dir)
570			seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
571	
572			alt := `{"modulus":"7","constraints":[
573				{"a":[{"wire":1,"coeff":"3"}],"b":[],"c":[]}]}`
574			altPath := writeTempJSON(t, alt)
575	
576			var wg sync.WaitGroup
577			start := make(chan struct{})
578			wg.Add(2)
579			go func() {
580				defer wg.Done()
581				<-start
582				for range 200 {
583					if _, err := s.ImportConstraints("c", 1, altPath); err != nil {
584						if !errors.Is(err, ErrFrozen) {
585							t.Errorf("unexpected import error: %v", err)
586						}
587						return
588					}
589				}
590			}()
591			go func() {
592				defer wg.Done()
593				<-start
594				s.FreezeCircuit("c", 1)
595			}()
596			close(start)
597			wg.Wait()
598	
599			c, err := s.GetCircuit("c", 1)
600			if err != nil {
601				t.Fatal(err)
602			}
603			if !c.Frozen {
604				t.Fatalf("iter %d: version not frozen", iter)
605			}
606			def, err := s.GetDefinition("c", 1)
607			if err != nil {
608				t.Fatalf("iter %d: frozen version must keep a complete definition: %v", iter, err)
609			}
610			// Every import of the same alt content is byte-identical, and the
611			// original is fully distinct: a mixed body is impossible. Just check
612			// the modulus is coherent and it recompiles to a stable hash.
613			a1, err := s.CompileCircuit("c", 1)
614			if err != nil {
615				t.Fatalf("iter %d: compile after race: %v", iter, err)
616			}
617			a2, _ := s.CompileCircuit("c", 1)
618			if a1 != a2 {
619				t.Fatalf("iter %d: artifact not stable: %+v %+v", iter, a1, a2)
620			}
621			if len(def.Constraints) != 1 {
622				t.Fatalf("iter %d: bad definition %+v", iter, def)
623			}
624			s.Close()
625	
626			s2, err := Open(dir)
627			if err != nil {
628				t.Fatalf("iter %d: reopen: %v", iter, err)
629			}
630			got, err := s2.GetArtifact("c", 1)
631			s2.Close()
632			if err != nil || got != a1 {
633				t.Fatalf("iter %d: reopened artifact mismatch: %+v %v", iter, got, err)
634			}
635		}
636	}
